PAIR_BINDINGS={'warp_divergent_pair_v2': {'kernel_symbol': 'warp_divergent_pair_v2', 'instruction_count': 560, 'target_identity_sha256': 'b08a1ec4253ca1a045fdd0d17081637481730110dcb4bd47980e3361ec621f54', 'registers_per_thread': 22, 'static_smem_bytes': 136, 'barriers': 1}, 'cta_divergent_pair_v2': {'kernel_symbol': 'cta_divergent_pair_v2', 'instruction_count': 120, 'target_identity_sha256': 'b1e06ea0f72bb4fd5a237f0f0c1958e737146ea5a0e536814d63a0dfbc3d7a0f', 'registers_per_thread': 25, 'static_smem_bytes': 136, 'barriers': 2}}
